camProcessedExpRow *camProcessedExpRowAlloc(psS64 cam_id, const char *uri, psF32 bg, psF32 bg_stdev, psF32 bg_mean_stdev, psF32 bias, psF32 bias_stdev, psF32 fringe_0, psF32 fringe_1, psF32 fringe_2, psF32 sigma_ra, psF32 sigma_dec, psF32 ap_resid, psF32 ap_resid_stdev, psF32 zp_mean, psF32 zp_stdev, psF32 fwhm_major, psF32 fwhm_minor, psF32 iq_m2, psF32 iq_m2_err, psF32 iq_m2_lq, psF32 iq_m2_uq, psF32 iq_m2c, psF32 iq_m2c_err, psF32 iq_m2c_lq, psF32 iq_m2c_uq, psF32 iq_m2s, psF32 iq_m2s_err, psF32 iq_m2s_lq, psF32 iq_m2s_uq, psF32 iq_m3, psF32 iq_m3_err, psF32 iq_m3_lq, psF32 iq_m3_uq, psF32 iq_m4, psF32 iq_m4_err, psF32 iq_m4_lq, psF32 iq_m4_uq, psF32 dtime_script, psF32 dtime_astrom, psF32 dtime_addstar, const char *hostname, psS32 n_stars, psS32 n_psfstars, psS32 n_iqstars, psS32 n_extended, psS32 n_cr, psS32 n_astrom, const char *path_base, psS16 fault)
{
    camProcessedExpRow *_object;

    _object = psAlloc(sizeof(camProcessedExpRow));
    psMemSetDeallocator(_object, (psFreeFunc)camProcessedExpRowFree);

    _object->cam_id = cam_id;
    _object->uri = psStringCopy(uri);
    _object->bg = bg;
    _object->bg_stdev = bg_stdev;
    _object->bg_mean_stdev = bg_mean_stdev;
    _object->bias = bias;
    _object->bias_stdev = bias_stdev;
    _object->fringe_0 = fringe_0;
    _object->fringe_1 = fringe_1;
    _object->fringe_2 = fringe_2;
    _object->sigma_ra = sigma_ra;
    _object->sigma_dec = sigma_dec;
    _object->ap_resid = ap_resid;
    _object->ap_resid_stdev = ap_resid_stdev;
    _object->zp_mean = zp_mean;
    _object->zp_stdev = zp_stdev;
    _object->fwhm_major = fwhm_major;
    _object->fwhm_minor = fwhm_minor;
    _object->iq_m2 = iq_m2;
    _object->iq_m2_err = iq_m2_err;
    _object->iq_m2_lq = iq_m2_lq;
    _object->iq_m2_uq = iq_m2_uq;
    _object->iq_m2c = iq_m2c;
    _object->iq_m2c_err = iq_m2c_err;
    _object->iq_m2c_lq = iq_m2c_lq;
    _object->iq_m2c_uq = iq_m2c_uq;
    _object->iq_m2s = iq_m2s;
    _object->iq_m2s_err = iq_m2s_err;
    _object->iq_m2s_lq = iq_m2s_lq;
    _object->iq_m2s_uq = iq_m2s_uq;
    _object->iq_m3 = iq_m3;
    _object->iq_m3_err = iq_m3_err;
    _object->iq_m3_lq = iq_m3_lq;
    _object->iq_m3_uq = iq_m3_uq;
    _object->iq_m4 = iq_m4;
    _object->iq_m4_err = iq_m4_err;
    _object->iq_m4_lq = iq_m4_lq;
    _object->iq_m4_uq = iq_m4_uq;
    _object->dtime_script = dtime_script;
    _object->dtime_astrom = dtime_astrom;
    _object->dtime_addstar = dtime_addstar;
    _object->hostname = psStringCopy(hostname);
    _object->n_stars = n_stars;
    _object->n_psfstars = n_psfstars;
    _object->n_iqstars = n_iqstars;
    _object->n_extended = n_extended;
    _object->n_cr = n_cr;
    _object->n_astrom = n_astrom;
    _object->path_base = psStringCopy(path_base);
    _object->fault = fault;

    return _object;
}

static void camProcessedExpRowFree(camProcessedExpRow *object)
{
    psFree(object->uri);
    psFree(object->hostname);
    psFree(object->path_base);
}

