pstampProjectRow *pstampProjectObjectFromMetadata(psMetadata *md)
{

bool status = false;
    psS64 proj_id = psMetadataLookupS64(&status, md, "proj_id");
    if (!status) {
        psError(PS_ERR_UNKNOWN, true, "failed to lookup value for item proj_id");
        return false;
    }
    char* name = psMetadataLookupPtr(&status, md, "name");
    if (!status) {
        psError(PS_ERR_UNKNOWN, true, "failed to lookup value for item name");
        return false;
    }
    char* state = psMetadataLookupPtr(&status, md, "state");
    if (!status) {
        psError(PS_ERR_UNKNOWN, true, "failed to lookup value for item state");
        return false;
    }
    char* dbname = psMetadataLookupPtr(&status, md, "dbname");
    if (!status) {
        psError(PS_ERR_UNKNOWN, true, "failed to lookup value for item dbname");
        return false;
    }
    char* dvodb = psMetadataLookupPtr(&status, md, "dvodb");
    if (!status) {
        psError(PS_ERR_UNKNOWN, true, "failed to lookup value for item dvodb");
        return false;
    }
    char* camera = psMetadataLookupPtr(&status, md, "camera");
    if (!status) {
        psError(PS_ERR_UNKNOWN, true, "failed to lookup value for item camera");
        return false;
    }
    char* telescope = psMetadataLookupPtr(&status, md, "telescope");
    if (!status) {
        psError(PS_ERR_UNKNOWN, true, "failed to lookup value for item telescope");
        return false;
    }
    bool need_magic = psMetadataLookupBool(&status, md, "need_magic");
    if (!status) {
        psError(PS_ERR_UNKNOWN, true, "failed to lookup value for item need_magic");
        return false;
    }

    return pstampProjectRowAlloc(proj_id, name, state, dbname, dvodb, camera, telescope, need_magic);
}
psArray *pstampProjectSelectRowObjects(psDB *dbh, const psMetadata *where, unsigned long long limit)
{
    psArray         *rowSet;
    psArray         *returnSet;
    psU64           i;

    rowSet = psDBSelectRows(dbh, PSTAMPPROJECT_TABLE_NAME, where, limit);
    if (!rowSet) {
        return NULL;
    }

    // convert psMetadata rows to row objects

    returnSet = psArrayAllocEmpty(rowSet->n);

    for (i = 0; i < rowSet->n; i++) {
        pstampProjectRow *object = pstampProjectObjectFromMetadata(rowSet->data[i]);
        if (!object) {
            psFree(object);
            psFree(returnSet);
            psError(PS_ERR_UNKNOWN, false, "database error");
            return NULL;
        }
        psArrayAdd(returnSet, 0, object);
        psFree(object);
    }

    psFree(rowSet);

    return returnSet;
}
bool pstampProjectDeleteObject(psDB *dbh, const pstampProjectRow *object)
{
    psMetadata *where = pstampProjectMetadataFromObject(object);
    long long count = psDBDeleteRows(dbh, PSTAMPPROJECT_TABLE_NAME, where, 0);
    psFree(where);
    if (count < 0) {
        psError(PS_ERR_UNKNOWN, true, "failed to delete row from pstampProject");
        return false;
    }
    if (count > 1) {
        // XXX should this be a psAbort() instead?  It is possible that
        // having an object match multiple rows was by design.
        psError(PS_ERR_UNKNOWN, true, "pstampProjectRow object matched more then one row.  Check your database schema");
        return false;
    }

    return true;
}
long long pstampProjectDeleteRowObjects(psDB *dbh, const psArray *objects, unsigned long long limit)
{
    long long       deleted = 0;

    for (long long i = 0; i < objects->n; i++) {
        pstampProjectRow *object = objects->data[i];
        psMetadata *where = pstampProjectMetadataFromObject(object);
        long long count = psDBDeleteRows(dbh, PSTAMPPROJECT_TABLE_NAME, where, limit);
        psFree(where);
        if (count < 0) {
            psError(PS_ERR_UNKNOWN, true, "failed to delete row from pstampProject");
            return count;
        }

        deleted += count;
    }

    return deleted;
}
